(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,32180,a=>{"use strict";let n={id:"kebugaran-jasmani",version:1,title:"Kebugaran Jasmani dan Latihan Fisik",mapel:"PJOK",kelas:"X",themeId:"globalisasi",navbar:{logoText:"💪 Kebugaran Jasmani",logoColor:"y",progressGradient:["y","g"]},screens:[{id:"s-cover",templateType:"cover",background:{type:"radial",color1:"y",color2:"bg"},blocks:[{type:"cover",icon:"💪",title:"Kebugaran Jasmani & Latihan Fisik",subtitle:"PJOK Kelas X SMA — Pertemuan 1",badges:[{icon:"📋",text:"TP 3",color:"y"},{icon:"📖",text:"3 Materi",color:"c"},{icon:"🏥",text:"Studi Kasus",color:"g"},{icon:"🎮",text:"Kuis 6 Soal",color:"p"}],meta:{durasi:"80 Menit",fase:"Fase F",elemen:"Kebugaran & Kesehatan"},cta:{label:"▶ Mulai Pembelajaran",action:"s-tp"},background:{type:"gradient",color1:"y",color2:"bg"}}],nav:{next:"s-tp",nextLabel:"Tujuan Pembelajaran"}},{id:"s-tp",templateType:"tp",sectionLabel:"🎯 Tujuan Pembelajaran",sectionColor:"p",blocks:[{type:"tp",title:"Yang Akan Kamu",titleHighlight:"Kuasai Hari Ini",items:[{num:1,verb:"Menjelaskan",desc:"konsep kebugaran jasmani, komponen-komponen kebugaran, serta prinsip latihan fisik yang efektif dan aman",color:"y"},{num:2,verb:"Menganalisis",desc:"hubungan antara komponen kebugaran jasmani dengan kesehatan dan performa aktivitas sehari-hari",color:"c"},{num:3,verb:"Merancang",desc:"program latihan fisik sederhana berdasarkan prinsip FITT (Frequency, Intensity, Time, Type) untuk meningkatkan kebugaran pribadi",color:"g"}],profil:"🔗 Profil Pelajar Pancasila: Mandiri · Bernalar Kritis · Bergotong Royong",profilColor:"y"},{type:"alur",title:"⏱️ Alur Kegiatan 80 Menit",totalDurasi:"80",steps:[{dot:"p",durasi:"±10'",judul:"TP & Motivasi",deskripsi:"Tujuan pembelajaran dan pemantik kebugaran"},{dot:"y",durasi:"±15'",judul:"Materi 1",deskripsi:"Konsep & komponen kebugaran jasmani"},{dot:"c",durasi:"±15'",judul:"Materi 2",deskripsi:"Prinsip latihan fisik & FITT"},{dot:"g",durasi:"±10'",judul:"Studi Kasus",deskripsi:"Analisis program kebugaran"},{dot:"o",durasi:"±10'",judul:"Kuis",deskripsi:"Uji pemahaman 6 soal"},{dot:"r",durasi:"±10'",judul:"Refleksi & Rangkuman",deskripsi:"Portofolio + rangkuman konsep kunci"},{dot:"p",durasi:"±10'",judul:"Penutup",deskripsi:"Penugasan program latihan mandiri"}]}],nav:{prev:"s-cover",next:"s-materi1",nextLabel:"Mulai Materi"}},{id:"s-materi1",templateType:"materi",sectionLabel:"📖 Materi 1 · ±15 Menit",sectionColor:"y",blocks:[{type:"def-box",borderColor:"y",content:"<strong>Kebugaran jasmani</strong> adalah kemampuan dan kesanggupan tubuh untuk melakukan aktivitas sehari-hari secara efisien tanpa mengalami kelelahan berlebihan, serta masih memiliki cadangan energi untuk kegiatan lain. Menurut <strong>WHO</strong>, kebugaran jasmani adalah salah satu pilar kesehatan selain nutrisi, istirahat, dan kesehatan mental."},{type:"nc-grid",cards:[{icon:"💪",title:"Kekuatan Otot",body:"Kemampuan otot menghasilkan tenaga saat berkontraksi. Contoh: mengangkat beban, push-up, pull-up",color:"y"},{icon:"🫀",title:"Daya Tahan Kardiovaskular",body:"Kemampuan jantung, paru-paru, dan pembuluh darah menyuplai oksigen saat aktivitas berkelanjutan. Contoh: lari jarak jauh, berenang, bersepeda",color:"c"},{icon:"🏋️",title:"Daya Tahan Otot",body:"Kemampuan otot melakukan kontraksi berulang tanpa kelelahan. Contoh: plank, duduk di dinding (wall sit)",color:"g"},{icon:"🤸",title:"Kelentukan (Fleksibilitas)",body:"Kemampuan sendi bergerak dalam rentang gerak maksimal. Contoh: merentangkan kaki, membungkuk menyentuh jari kaki",color:"p"},{icon:"⚡",title:"Kecepatan",body:"Kemampuan menempuh jarak dalam waktu sesingkat mungkin. Contoh: sprint 100m, berenang 50m",color:"r"},{icon:"🔄",title:"Kelincahan",body:"Kemampuan mengubah arah gerakan dengan cepat dan tepat. Contoh: zig-zag run, shuttle run",color:"y"}]},{type:"tabel-accord",rows:[{icon:"🫀",title:"Daya Tahan Kardiovaskular",color:"c",details:[{label:"Definisi",value:"Kemampuan sistem jantung-paru-pembuluh darah menyuplai O₂ ke otot yang bekerja selama aktivitas berkelanjutan"},{label:"Latihan",value:"Lari jarak jauh, berenang, bersepeda, jalan cepat, aerobik (intensitas sedang, durasi panjang)"},{label:"Indikator",value:"Denyut nadi istirahat rendah (60-70 bpm), bisa beraktivitas 30+ menit tanpa kelelahan berlebihan"},{label:"Manfaat",value:"Mengurangi risiko penyakit jantung, stroke, diabetes tipe 2, dan obesitas"}]},{icon:"💪",title:"Kekuatan Otot",color:"y",details:[{label:"Definisi",value:"Kemampuan otot atau sekelompok otot menghasilkan tenaga maksimal saat berkontraksi"},{label:"Latihan",value:"Push-up, pull-up, squat, lunges, mengangkat beban (resistance training)"},{label:"Indikator",value:"Bisa melakukan push-up 15-20 kali, pull-up 5-8 kali, squat dengan beban tubuh"},{label:"Manfaat",value:"Meningkatkan metabolisme, menjaga kepadatan tulang, mencegah cedera, memperbaiki postur"}]},{icon:"🤸",title:"Kelentukan",color:"p",details:[{label:"Definisi",value:"Kemampuan sendi dan otot bergerak dalam rentang gerak maksimal tanpa rasa sakit"},{label:"Latihan",value:"Stretching statis, stretching dinamis, yoga, Pilates"},{label:"Indikator",value:"Bisa membungkuk menyentuh jari kaki tanpa menekuk lutut, merentangkan kaki lebar"},{label:"Manfaat",value:"Mencegah cedera otot dan sendi, memperbaiki postur, meningkatkan performa olahraga"}]}]},{type:"diskusi",title:"✍️ Latihan Mandiri",questions:[{label:"Latihan Mandiri",icon:"✍️",teks:"Dari enam komponen kebugaran di atas, komponen mana yang paling kamu rasakan perlu ditingkatkan? Mengapa?",petunjuk:"Tuliskan di sini… (jawabanmu akan tampil lagi di Refleksi)",color:"y"}]}],nav:{prev:"s-tp",next:"s-materi2",nextLabel:"Lanjut: Prinsip Latihan Fisik"}},{id:"s-materi2",templateType:"materi",sectionLabel:"📖 Materi 2 · ±15 Menit",sectionColor:"c",blocks:[{type:"materi-blok",tipe:"poin",judul:"Prinsip-Prinsip Latihan Fisik",icon:"📋",warna:"c",butir:["Prinsip Overload: beban latihan harus melebihi kebiasaan tubuh agar terjadi peningkatan (adaptasi). Tanpa overload, tubuh tidak akan berkembang","Prinsip Progresif: peningkatan beban latihan dilakukan secara bertahap (gradual), bukan drastis. Naikkan 10% per minggu","Prinsip Spesifisitas: latihan harus sesuai dengan komponen kebugaran yang ingin ditingkatkan. Untuk daya tahan → lari jauh, bukan angkat beban berat",'Prinsip Reversibilitas: kebugaran akan menurun jika latihan dihentikan. "Minggu ketiga tanpa latihan, kebugaran turun 10%"',"Prinsip Variasi: mengubah jenis latihan secara berkala agar tubuh tidak berhenti beradaptasi dan mencegah kejenuhan","Prinsip Individualisasi: program latihan harus disesuaikan dengan kondisi, kemampuan, dan tujuan masing-masing individu"]},{type:"materi-blok",tipe:"definisi",judul:"Prinsip FITT — Panduan Merancang Program Latihan",icon:"📊",warna:"g",isi:"FITT adalah singkatan dari Frequency, Intensity, Time, dan Type — empat variabel yang harus diperhatikan saat merancang program latihan fisik.",butir:["F — Frequency (Frekuensi): Seberapa sering latihan dilakukan. Rekomendasi: 3-5 kali/minggu untuk kardio, 2-3 kali/minggu untuk kekuatan","I — Intensity (Intensitas): Seberapa berat latihan tersebut. Dapat diukur dengan denyut nadi: 60-85% denyut nadi maksimal (220 - umur)","T — Time (Waktu): Durasi setiap sesi latihan. Rekomendasi: 30-60 menit per sesi untuk kardio, 20-45 menit untuk kekuatan","T — Type (Jenis): Jenis aktivitas yang sesuai tujuan. Kardio: lari, berenang, bersepeda. Kekuatan: angkat beban, bodyweight exercise"]},{type:"statistik",title:"Rekomendasi Aktivitas Fisik WHO untuk Remaja",items:[{warna:"y",angka:"60",satuan:"menit/hari",label:"Aktivitas fisik moderat-berat",icon:"🏃"},{warna:"c",angka:"3",satuan:"kali/minggu",label:"Latihan kekuatan otot & tulang",icon:"💪"},{warna:"g",angka:"150",satuan:"menit/minggu",label:"Minimum aktivitas aerobik",icon:"🫀"}],accentColor:"c"},{type:"def-box",borderColor:"c",content:"<strong>💡 Menghitung Denyut Nadi Latihan:</strong> Gunakan rumus Karvonen. Denyut nadi maksimal = 220 − umur. Zona latihan efektif = 60–85% DNM. Contoh untuk usia 16 tahun: DNM = 220 − 16 = 204 bpm. Zona latihan = 122–173 bpm."},{type:"flashcard-set",cards:[{q:"Apa yang dimaksud prinsip overload?",a:"Beban latihan harus melebihi kebiasaan tubuh agar terjadi peningkatan (adaptasi). Tanpa overload, tubuh tidak akan berkembang karena sudah terbiasa."},{q:"Apa kepanjangan FITT dan apa fungsinya?",a:"Frequency, Intensity, Time, Type. FITT adalah panduan merancang program latihan fisik yang efektif dengan mengatur empat variabel utama latihan."},{q:"Berapa denyut nadi maksimal untuk usia 16 tahun?",a:"220 − 16 = 204 bpm. Zona latihan efektifnya adalah 60–85% × 204 = 122–173 bpm."},{q:"Apa konsekuensi dari prinsip reversibilitas?",a:"Kebugaran akan menurun jika latihan dihentikan. Penelitian menunjukkan kebugaran turun sekitar 10% setelah 2-3 minggu tanpa latihan."}]},{type:"diskusi",title:"💬 Diskusi Kelas (±5 menit)",questions:[{label:"Diskusi Kelas",icon:"💬",teks:"Menurutmu, mengapa banyak orang yang mulai berolahraga tapi berhenti di tengah jalan? Prinsip latihan mana yang tidak dipenuhi?",petunjuk:"Tuliskan pendapatmu di sini… (akan tampil di Refleksi)",color:"c"}]}],nav:{prev:"s-materi1",next:"s-studi",nextLabel:"Lanjut: Studi Kasus"}},{id:"s-studi",templateType:"materi",sectionLabel:"🏥 Studi Kasus · ±10 Menit",sectionColor:"g",blocks:[{type:"studi",title:"Studi Kasus: Program Kebugaran Rina",karakter:"Rina (16 tahun)",situasi:"Rina adalah siswi kelas X SMA yang merasa cepat lelah saat naik tangga ke lantai 3 dan sering mengantuk di kelas. Ia jarang berolahraga dan lebih banyak duduk belajar atau bermain ponsel. Setelah konsultasi dengan guru PJOK, Rina ingin memulai program latihan fisik.",pertanyaan:"Berdasarkan prinsip FITT, rancanglah program latihan 1 minggu untuk Rina yang masih pemula! Tentukan Frequency, Intensity, Time, dan Type yang sesuai untuknya!",pesan:"Perhatikan bahwa Rina masih pemula — prinsip progresif harus diterapkan! Jangan langsung memberikan latihan berat. Mulai dari intensitas rendah dan tingkatkan secara bertahap. Pastikan juga ada hari istirahat untuk pemulihan.",accentColor:"g"},{type:"nc-grid",cards:[{icon:"📅",title:"Contoh Program Senin",body:"Jalan cepat 20 menit (Intensity: 60% DNM) + Stretching 10 menit. Ini adalah awal yang aman untuk pemula!",color:"y"},{icon:"📅",title:"Contoh Program Rabu",body:"Jogging 15 menit + Push-up 3×5 repetisi + Plank 3×20 detik. Mulai tambahkan latihan kekuatan dasar",color:"c"},{icon:"📅",title:"Contoh Program Jumat",body:"Bersepeda santai 25 menit + Squat 3×8 repetisi + Stretching. Variasi jenis latihan agar tidak membosankan",color:"g"},{icon:"📅",title:"Hari Istirahat",body:"Selasa, Kamis, Sabtu, Minggu: Istirahat aktif (jalan santai, stretching ringan). Tubuh perlu pemulihan!",color:"p"}]}],nav:{prev:"s-materi2",next:"s-kuis",nextLabel:"Lanjut ke Kuis 🎮"}},{id:"s-kuis",templateType:"game",sectionLabel:"🎮 Kuis · ±10 Menit",sectionColor:"y",blocks:[{type:"roda-game",title:"Roda Kebugaran Jasmani!",questions:[{q:"Apa yang dimaksud dengan kebugaran jasmani?",diskusiHint:"Kemampuan tubuh melakukan aktivitas...",opts:[{text:"Kemampuan mengangkat beban seberat mungkin",correct:!1},{text:"Kemampuan tubuh melakukan aktivitas sehari-hari secara efisien tanpa kelelahan berlebihan",correct:!0},{text:"Kemampuan berlari secepat mungkin",correct:!1},{text:"Kemampuan tubuh tidak pernah sakit",correct:!1}],feedbackCorrect:"Benar! Kebugaran jasmani adalah kemampuan dan kesanggupan tubuh melakukan aktivitas sehari-hari secara efisien tanpa kelelahan berlebihan, dengan cadangan energi untuk kegiatan lain.",feedbackWrong:"Kebugaran jasmani adalah kemampuan tubuh melakukan aktivitas sehari-hari secara efisien tanpa kelelahan berlebihan — bukan hanya soal kekuatan atau kecepatan."},{q:'Prinsip latihan yang menyatakan "beban harus melebihi kebiasaan tubuh" disebut prinsip...',diskusiHint:"Beban yang lebih dari biasanya...",opts:[{text:"Progresif",correct:!1},{text:"Spesifisitas",correct:!1},{text:"Overload",correct:!0},{text:"Variasi",correct:!1}],feedbackCorrect:"Benar! Prinsip overload menyatakan bahwa beban latihan harus melebihi kebiasaan tubuh agar terjadi adaptasi dan peningkatan kebugaran.",feedbackWrong:"Prinsip overload: beban latihan harus melebihi kebiasaan tubuh. Prinsip progresif = peningkatan bertahap, spesifisitas = latihan sesuai tujuan, variasi = mengubah jenis latihan."},{q:'Huruf "I" dalam prinsip FITT merupakan singkatan dari...',diskusiHint:"Seberapa berat latihan tersebut...",opts:[{text:"Interval",correct:!1},{text:"Intensity (Intensitas)",correct:!0},{text:"Incline",correct:!1},{text:"Inertia",correct:!1}],feedbackCorrect:"Benar! I = Intensity (Intensitas), yaitu seberapa berat latihan tersebut. Dapat diukur dengan denyut nadi di zona 60-85% DNM.",feedbackWrong:"I = Intensity (Intensitas) — mengukur seberapa berat latihan. Diukur dengan denyut nadi, beban, atau tingkat kesulitan."},{q:"Berapa rekomendasi WHO aktivitas fisik harian untuk remaja?",diskusiHint:"WHO merekomendasikan durasi per hari...",opts:[{text:"30 menit per hari",correct:!1},{text:"60 menit per hari",correct:!0},{text:"90 menit per hari",correct:!1},{text:"120 menit per hari",correct:!1}],feedbackCorrect:"Benar! WHO merekomendasikan minimal 60 menit aktivitas fisik moderat hingga berat per hari untuk remaja usia 5-17 tahun.",feedbackWrong:"WHO merekomendasikan minimal 60 menit aktivitas fisik moderat hingga berat per hari untuk remaja, ditambah latihan kekuatan otot dan tulang minimal 3 kali per minggu."},{q:"Prinsip yang menyatakan bahwa kebugaran akan menurun jika latihan dihentikan disebut...",diskusiHint:"Jika berhenti latihan, kebugaran kembali turun...",opts:[{text:"Prinsip progresif",correct:!1},{text:"Prinsip overload",correct:!1},{text:"Prinsip reversibilitas",correct:!0},{text:"Prinsip individualisasi",correct:!1}],feedbackCorrect:'Benar! Prinsip reversibilitas menyatakan bahwa kebugaran akan menurun jika latihan dihentikan. "Use it or lose it!" — kebugaran turun sekitar 10% setelah 2-3 minggu tanpa latihan.',feedbackWrong:'Prinsip reversibilitas: kebugaran menurun jika latihan dihentikan. Ini seperti "use it or lose it" — penurunan sekitar 10% setelah 2-3 minggu tanpa latihan.'},{q:"Denyut nadi maksimal seseorang berusia 16 tahun adalah...",diskusiHint:"Gunakan rumus 220 dikurangi umur",opts:[{text:"180 bpm",correct:!1},{text:"196 bpm",correct:!1},{text:"204 bpm",correct:!0},{text:"210 bpm",correct:!1}],feedbackCorrect:"Benar! DNM = 220 − 16 = 204 bpm. Zona latihan efektifnya adalah 60-85% × 204 = 122-173 bpm.",feedbackWrong:"Rumus denyut nadi maksimal = 220 − umur. Untuk usia 16 tahun: 220 − 16 = 204 bpm. Zona latihan efektif = 122-173 bpm."}]}],nav:{prev:"s-studi",next:"s-hasil",nextLabel:"Lihat Hasil 🏆"}},{id:"s-hasil",templateType:"hasil",sectionLabel:"🏆 Hasil",sectionColor:"y",background:{type:"radial",color1:"y",color2:"bg"},blocks:[{type:"hasil",title:"Kebugaran Jasmani",subtitle:"Pertemuan 1 Selesai! 🎉"}],nav:{prev:"s-kuis",next:"s-refleksi",nextLabel:"Refleksi Diri 📝"}},{id:"s-refleksi",templateType:"refleksi",sectionLabel:"📝 Refleksi · ±10 Menit",sectionColor:"p",blocks:[{type:"refleksi",title:"Refleksi Diri",intro:"Jawaban jujurmu lebih berharga dari jawaban yang sempurna.",questions:[{teks:"Hal baru apa yang kamu pelajari hari ini tentang kebugaran jasmani dan prinsip latihan?",petunjuk:"Tuliskan 1–2 hal yang benar-benar baru bagimu…",warna:"y",icon:"🌟"},{teks:"Dari semua komponen kebugaran, mana yang paling perlu kamu tingkatkan? Apa langkah konkret yang akan kamu ambil?",petunjuk:"Jelaskan rencana latihanmu berdasarkan prinsip FITT…",warna:"c",icon:"🔍"},{teks:"Satu komitmen nyata untuk meningkatkan kebugaranmu minggu ini:",petunjuk:"Contoh: Saya akan jogging 3 kali seminggu selama 20 menit setiap pagi",warna:"g",icon:"🤝"}],penugasan:{judul:"📌 Penugasan: Rancang Program Latihan 1 Minggu",isi:"Buatlah program latihan fisik pribadi selama 1 minggu berdasarkan prinsip FITT. Tentukan: Frequency (berapa kali/minggu), Intensity (zona denyut nadi), Time (durasi per sesi), dan Type (jenis latihan). Catat hasilnya dan laporkan di pertemuan berikutnya!",contoh:"Contoh: Senin — Jogging 20 menit (65% DNM) + Push-up 3×8 + Stretching 10 menit. Rabu — Bersepeda 25 menit + Squat 3×10 + Plank 3×30 detik. Jumat — Lari interval 15 menit + Latihan kekuatan upper body + Cool down."}}],nav:{prev:"s-hasil",next:"s-rangkuman",nextLabel:"Rangkuman"}},{id:"s-rangkuman",templateType:"materi",sectionLabel:"📋 Rangkuman · ±5 Menit",sectionColor:"y",blocks:[{type:"rangkuman",title:"Rangkuman Kebugaran Jasmani",concepts:[{icon:"💪",title:"Kebugaran Jasmani",body:"Kemampuan tubuh melakukan aktivitas sehari-hari secara efisien tanpa kelelahan berlebihan, dengan cadangan energi untuk kegiatan lain",color:"y"},{icon:"📊",title:"6 Komponen Kebugaran",body:"Kekuatan otot, daya tahan kardiovaskular, daya tahan otot, kelentukan, kecepatan, dan kelincahan",color:"c"},{icon:"📋",title:"Prinsip Latihan",body:"Overload, progresif, spesifisitas, reversibilitas, variasi, dan individualisasi — harus diterapkan agar latihan efektif",color:"g"},{icon:"🎯",title:"Prinsip FITT",body:"Frequency (frekuensi), Intensity (intensitas), Time (waktu), Type (jenis) — panduan merancang program latihan yang terukur",color:"p"},{icon:"🫀",title:"Zona Latihan",body:"60-85% denyut nadi maksimal (220-umur) — zona efektif untuk meningkatkan kebugaran kardiovaskular",color:"r"}],closingStatement:'Ingat: Kebugaran bukan tujuan akhir, melainkan gaya hidup. Mulai dari yang kecil, lakukan secara konsisten, dan tingkatkan secara bertahap. "The best time to start was yesterday. The second best time is now!"',accentColor:"y"}],nav:{prev:"s-refleksi",next:"s-penutup",nextLabel:"Penutup"}},{id:"s-penutup",templateType:"penutup",background:{type:"radial",color1:"y",color2:"bg"},blocks:[{type:"penutup",title:"Pertemuan 1",subtitle:"Kebugaran Jasmani — Berhasil Diselesaikan!",preview:[{icon:"💪",judul:"Komponen Kebugaran",isi:"6 komponen kebugaran jasmani",warna:"y"},{icon:"📋",judul:"Prinsip Latihan",isi:"6 prinsip + prinsip FITT",warna:"c"},{icon:"🎯",judul:"Program Latihan",isi:"Merancang program berdasarkan FITT",warna:"g"}],nextPertemuan:{judul:"Pertemuan 2: Pengukuran Kebugaran Jasmani",deskripsi:"Di pertemuan berikutnya, kita akan mempraktikkan tes kebugaran jasmani: tes lari 2,4 km, tes push-up 1 menit, tes sit-up 1 menit, dan tes sit-and-reach untuk mengukur tingkat kebugaran masing-masing!",items:[{icon:"🏃",judul:"Tes Lari 2,4 km",isi:"Mengukur daya tahan kardiovaskular",warna:"y"},{icon:"💪",judul:"Tes Push-up & Sit-up",isi:"Mengukur daya tahan dan kekuatan otot",warna:"c"},{icon:"🤸",judul:"Tes Sit-and-Reach",isi:"Mengukur kelentukan (fleksibilitas)",warna:"g"}]}}]}]};a.s(["KEBUGARAN_JASMANI_LESSON",0,n])}]);